/** A typed client for the CrawlerAI API over `fetch`: no runtime dependencies. Request and answer types come from the
 * API's OpenAPI document (`schema.d.ts`, generated by `pnpm gen`). */
import type { components } from "./schema.js";
import { parseEvents, type JobEvent } from "./events.js";

export { parseEvents, type JobEvent } from "./events.js";
export { signWebhook, verifyWebhook, parseWebhook, SIGNATURE_HEADER } from "./webhooks.js";
export type { components } from "./schema.js";

type S = components["schemas"];

/** The requests, as the API's schemas define them; members with a server default are optional. */
export type ScrapeRequest = S["ScrapeRequest"];
export type MapRequest = S["MapRequest"];
export type CrawlRequest = S["CrawlRequest"];
export type BatchScrapeRequest = S["BatchScrapeRequest"];
export type ExtractRequest = S["ExtractRequest"];
export type SearchRequest = S["SearchRequest"];

export type ScrapeResult = S["ScrapeResult"];
export type MapResult = S["MapResult"];
export type SearchResult = S["SearchResult"];
export type SearchHit = S["SearchHit"];
export type JobSummary = S["JobSummary"];
export type JobStatus = JobSummary["status"];
export type Problem = S["Problem"];

/** `url` without the slashes that end it. */
function trimSlashes(url: string): string {
  let end = url.length;
  while (end > 0 && url[end - 1] === "/") end -= 1;
  return url.slice(0, end);
}

/** The members of an error body when it is a JSON object (RFC 9457 §3: a problem document is one); anything else
 * (`null`, a number, a string, an array) carries none. */
function asProblem(parsed: unknown): Partial<Problem> {
  return typeof parsed === "object" && parsed !== null && !Array.isArray(parsed) ? (parsed as Partial<Problem>) : {};
}

/** `/v1/jobs/{id}` with the id as one percent-encoded path segment (RFC 3986 §3.3), so `/`, `?` or `#` in it cannot
 * change the path or add a query. */
function jobPath(jobId: string): string {
  return `/v1/jobs/${encodeURIComponent(jobId)}`;
}

const ENDED: ReadonlySet<JobStatus> = new Set(["completed", "failed", "cancelled"]);

// setTimeout takes a signed 32-bit millisecond count; a longer delay fires at once.
const MAX_TIMER_MS = 2 ** 31 - 1;

/** The API answered with a problem document (RFC 9457): `type` is its code (`validation`, `search_unavailable`, ...). */
export class APIError extends Error {
  readonly status: number;
  readonly problem: Partial<Problem>;
  constructor(status: number, problem: Partial<Problem>) {
    super(`${String(status)} ${problem.type ?? "error"}: ${problem.detail ?? problem.title ?? ""}`);
    this.name = "APIError";
    this.status = status;
    this.problem = problem;
  }
  get type(): string {
    return this.problem.type ?? "error";
  }
}

/** `waitForJob` gave up before the job ended. */
export class JobTimeout extends Error {
  constructor(
    readonly jobId: string,
    seconds: number,
  ) {
    super(`job ${jobId} did not end within ${String(seconds)} s`);
    this.name = "JobTimeout";
  }
}

export interface ClientOptions {
  /** The API's origin; default `http://localhost:8000`. */
  baseUrl?: string;
  /** A `fetch` to use instead of the global one (a test double, a proxy-aware one). */
  fetch?: typeof fetch;
}

export interface ResultsPage {
  items: Record<string, unknown>[];
  next_cursor: string | null;
}

/** The client. Each request method sends exactly the members given, so the server's defaults apply to the rest. */
export class CrawlerAI {
  readonly #base: string;
  readonly #key: string;
  readonly #fetch: typeof fetch;

  constructor(apiKey: string, options: ClientOptions = {}) {
    this.#key = apiKey;
    this.#base = trimSlashes(options.baseUrl ?? "http://localhost:8000");
    this.#fetch = options.fetch ?? ((...args) => fetch(...args));
  }

  async #send(method: string, path: string, init: { body?: unknown; query?: Record<string, string>; accept?: string; headers?: Record<string, string> } = {}): Promise<Response> {
    const query = init.query === undefined ? "" : `?${new URLSearchParams(init.query).toString()}`;
    const headers: Record<string, string> = {
      Authorization: `Bearer ${this.#key}`,
      Accept: init.accept ?? "application/json",
      ...init.headers,
    };
    if (init.body !== undefined) headers["Content-Type"] = "application/json";
    const response = await this.#fetch(`${this.#base}${path}${query}`, {
      method,
      headers,
      ...(init.body === undefined ? {} : { body: JSON.stringify(init.body) }),
    });
    if (!response.ok) {
      throw new APIError(response.status, asProblem(await response.json().catch(() => null)));
    }
    return response;
  }

  async #json<T>(method: string, path: string, body?: unknown, query?: Record<string, string>): Promise<T> {
    const response = await this.#send(method, path, {
      ...(body === undefined ? {} : { body }),
      ...(query === undefined ? {} : { query }),
    });
    return (await response.json()) as T;
  }

  /** `POST /v1/scrape`: one page, fetched while you wait. */
  scrape(request: ScrapeRequest): Promise<ScrapeResult> {
    return this.#json("POST", "/v1/scrape", request);
  }

  /** `POST /v1/map`: the URLs of a site. */
  map(request: MapRequest): Promise<MapResult> {
    return this.#json("POST", "/v1/map", request);
  }

  /** `POST /v1/search`: web results; `scrape` scrapes them in a batch job (`job_id` of the answer). Rejects with an
   * `APIError` of type `search_unavailable` (503) when the operator has configured no search provider. */
  search(request: SearchRequest): Promise<SearchResult> {
    return this.#json("POST", "/v1/search", request);
  }

  /** `POST /v1/crawl`: queue a crawl; `strategy: "best_first"` with a `query` fetches the best-matching pages first. */
  crawl(request: CrawlRequest): Promise<{ job_id: string }> {
    return this.#json("POST", "/v1/crawl", request);
  }

  /** `POST /v1/batch/scrape`: queue a scrape of many URLs. */
  batchScrape(request: BatchScrapeRequest): Promise<{ job_id: string }> {
    return this.#json("POST", "/v1/batch/scrape", request);
  }

  /** `POST /v1/extract`: queue the extraction of a record from each URL. */
  extract(request: ExtractRequest): Promise<{ job_id: string }> {
    return this.#json("POST", "/v1/extract", request);
  }

  /** `GET /v1/jobs/{id}`. */
  job(jobId: string): Promise<JobSummary> {
    return this.#json("GET", jobPath(jobId));
  }

  /** `DELETE /v1/jobs/{id}`: ask the job to stop. */
  cancelJob(jobId: string): Promise<JobSummary> {
    return this.#json("DELETE", jobPath(jobId));
  }

  /** One page of `GET /v1/jobs/{id}/results`. */
  jobResults(jobId: string, page: { cursor?: string; limit?: number } = {}): Promise<ResultsPage> {
    const query: Record<string, string> = { format: "json" };
    if (page.cursor !== undefined) query["cursor"] = page.cursor;
    if (page.limit !== undefined) query["limit"] = String(page.limit);
    return this.#json("GET", `${jobPath(jobId)}/results`, undefined, query);
  }

  /** Every result of the job, page after page. */
  async *iterJobResults(jobId: string, pageSize?: number): AsyncGenerator<Record<string, unknown>> {
    let cursor: string | undefined;
    for (;;) {
      const page = await this.jobResults(jobId, {
        ...(cursor === undefined ? {} : { cursor }),
        ...(pageSize === undefined ? {} : { limit: pageSize }),
      });
      yield* page.items;
      if (page.next_cursor === null) return;
      cursor = page.next_cursor;
    }
  }

  /** Poll the job until it is `completed`, `failed` or `cancelled`, and return its summary. Rejects with `JobTimeout`
   * after `timeoutS` seconds (never, when absent). */
  waitForJob(jobId: string, options: { pollIntervalS?: number; timeoutS?: number } = {}): Promise<JobSummary> {
    const deadline = options.timeoutS === undefined ? Infinity : Date.now() + options.timeoutS * 1000;
    return this.#poll(jobId, (options.pollIntervalS ?? 1) * 1000, deadline, options.timeoutS ?? 0);
  }

  async #poll(jobId: string, intervalMs: number, deadline: number, timeoutS: number, last = false): Promise<JobSummary> {
    const summary = await this.job(jobId);
    if (ENDED.has(summary.status)) return summary;
    const left = deadline - Date.now();
    if (last || left <= 0) throw new JobTimeout(jobId, timeoutS);
    // Never sleep past the deadline: the last poll happens at it, not up to an interval after it. A poll after a sleep
    // to the deadline is the last one, since a timer may fire a millisecond before the clock reaches it.
    const wait = Math.min(intervalMs, left, MAX_TIMER_MS);
    await new Promise((resolve) => setTimeout(resolve, wait));
    return this.#poll(jobId, intervalMs, deadline, timeoutS, wait >= left);
  }

  /** The job's run events live (`GET /v1/jobs/{id}/events`), until its end event; resume with the last id seen. */
  async *events(jobId: string, lastEventId?: string): AsyncGenerator<JobEvent> {
    const response = await this.#send("GET", `${jobPath(jobId)}/events`, {
      accept: "text/event-stream",
      ...(lastEventId === undefined ? {} : { headers: { "Last-Event-ID": lastEventId } }),
    });
    if (response.body === null) return;
    yield* parseEvents(response.body);
  }
}
